/* ===================== BÀI 57 · Đặc tả và phân rã hệ thống ===================== */
/* Bài 57 · Đặc tả và phân rã hệ thống (AMTS-EMB-001-M15-L01, MC51-057) — sinh bởi tools/author/mcu8051/l57.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P57=[{"label":"Ví dụ: I/O map thành mặt nạ bit","code":"; I/O map của cổng P2 viết thành mặt nạ bit\nSEL7    EQU     0FH                     ; P2.0–P2.3: chọn chữ số LED 7 đoạn\nCANHBAO EQU     80H                     ; P2.7: đèn cảnh báo\nLCDD    EQU     0FFH                    ; LCD 8 bit muốn dùng D0–D7 = P2\n        ORG     0000H\n        MOV     A,#SEL7\n        ORL     A,#CANHBAO              ; A = các chân P2 đã cấp phát\n        MOV     30H,A\n        ANL     A,#LCDD                 ; chân LCD trùng chân đã cấp\n        MOV     31H,A                   ; khác 0 nghĩa là xung đột\n        SJMP    $\n        END\n","note":"Ba dòng EQU không sinh byte mã nào: chúng chỉ đặt tên cho mặt nạ. Đoán trước: sau ANL A,#LCDD, ô 31H bằng bao nhiêu? (8FH: LCD 8 bit đụng cả 4 chân chọn chữ số và chân cảnh báo — phải chuyển LCD sang chế độ 4 bit ở cổng khác hoặc bỏ 7 đoạn.)","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Ngân sách thời gian của một tick","code":"; Ngân sách thời gian của một tick 1 ms (1 000 chu kỳ máy)\n        ORG     0000H\n        MOV     DPTR,#CHIPHI            ; bảng chi phí đo được của 4 tác vụ\n        MOV     R2,#0                   ; R2:R3 = tổng chu kỳ (16 bit)\n        MOV     R3,#0\n        MOV     R7,#4                   ; 4 tác vụ\n        MOV     R0,#0                   ; chỉ số trong bảng\nLAP:    MOV     A,R0\n        MOVC    A,@A+DPTR               ; chi phí tác vụ thứ R0\n        ADD     A,R3\n        MOV     R3,A\n        CLR     A\n        ADDC    A,R2                    ; cộng số nhớ vào byte cao\n        MOV     R2,A\n        INC     R0\n        DJNZ    R7,LAP\n        MOV     30H,R2                  ; tổng = 30H:31H\n        MOV     31H,R3\n        CLR     C                       ; dư = 700 − tổng (700 = 02BCH)\n        MOV     A,#0BCH\n        SUBB    A,R3\n        MOV     33H,A\n        MOV     A,#02H\n        SUBB    A,R2\n        MOV     32H,A                   ; dư = 32H:33H; CY = 1 nếu vượt\n        SJMP    $\nCHIPHI: DB      120,95,180,210          ; phím, 7 đoạn, đếm, UART\n        END\n","note":"Vòng lặp cộng 4 chi phí lấy từ bảng CHIPHI bằng MOVC. Đoán trước: tổng 120 + 95 + 180 + 210 bằng bao nhiêu ở hệ 16? (605 = 025DH: 30H = 02H, 31H = 5DH.) Phần cuối tính dư = 700 − 605 = 95 = 005FH, CY = 0 nghĩa là còn trong ngân sách. Chương trình chạy 61 chu kỳ máy.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Máy trạng thái bằng bảng","code":"; Máy trạng thái bằng bảng: trạng thái mới = NEXT[4×TT + SK]\n; TT: 0 CHỜ, 1 ĐẾM, 2 BÁO · SK: 0 có SP, 1 đủ hạn mức, 2 xóa\n        ORG     0000H\n        MOV     R5,#0                   ; trạng thái đầu: CHỜ\n        MOV     R4,#0                   ; chỉ số trong kịch bản sự kiện\n        MOV     R1,#40H                 ; vết trạng thái ghi từ 40H\nVONG:   MOV     DPTR,#SUKIEN\n        MOV     A,R4\n        MOVC    A,@A+DPTR               ; A = sự kiện kế tiếp\n        CJNE    A,#0FFH,BUOC            ; FFH = hết kịch bản\n        SJMP    XONG\nBUOC:   MOV     R6,A\n        MOV     A,R5\n        RL      A\n        RL      A                       ; A = 4 × trạng thái\n        ADD     A,R6                    ; + sự kiện\n        MOV     DPTR,#NEXT\n        MOVC    A,@A+DPTR               ; trạng thái mới\n        MOV     R5,A\n        MOV     @R1,A                   ; ghi vết\n        INC     R1\n        INC     R4\n        SJMP    VONG\nXONG:   MOV     30H,R5\n        SJMP    $\nNEXT:   DB      1,0,0,0                 ; từ CHỜ\n        DB      1,2,0,1                 ; từ ĐẾM\n        DB      2,2,0,2                 ; từ BÁO\nSUKIEN: DB      0,0,1,0,2,0,0FFH\n        END\n","note":"Kịch bản sự kiện SP, SP, đủ, SP, xóa, SP. Theo dõi R5 và vết ở 40H–45H: 01, 01, 02, 02, 00, 01. Đoán trước: sau sự kiện thứ ba (đủ hạn mức) R5 bằng mấy? (2: ĐẾM + đủ → BÁO.) Mỗi sự kiện tốn 22 chu kỳ máy; bài tập 3 yêu cầu làm nhanh hơn.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: SP mặc định 07H đè biến ở 08H","code":"; Biến đặt ở 08H nhưng quên đặt SP (sau reset SP = 07H)\nDEM     DATA    08H                     ; số sản phẩm đã đếm\n        ORG     0000H\n        MOV     DEM,#25                 ; đã đếm 25 = 19H\n        ACALL   HIEN                    ; cất địa chỉ trở về vào 08H, 09H\n        MOV     30H,DEM                 ; đọc lại biến đếm\n        SJMP    $\nHIEN:   NOP                             ; (cập nhật màn hình)\n        RET\n        END\n","note":"Biến DEM đặt ở 08H, nhưng SP sau reset = 07H. ACALL HIEN cất địa chỉ trở về 0005H vào 08H (byte thấp 05H) và 09H (00H): số đếm 25 bị ghi đè thành 5. Không có lỗi hay cảnh báo nào — chỉ ngân sách RAM ghi rõ ngăn xếp ở đâu mới tránh được. Sửa: MOV SP,#5FH ở đầu chương trình.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Đèn và bàn phím chung cổng P1","code":"; Đèn cảnh báo và ma trận phím cùng nối cổng P1\n        ORG     0000H\n        MOV     P1,#0FEH                ; bật đèn cảnh báo ở P1.0\n        ACALL   QUET                    ; quét một hàng bàn phím\n        SJMP    $\nQUET:   MOV     P1,#0FDH                ; hàng 2 (P1.1) = 0, cột = 1\n        MOV     A,P1                    ; đọc 4 cột P1.4–P1.7\n        ANL     A,#0F0H\n        MOV     30H,A                   ; F0H: không có phím nào\n        RET\n        END\n","note":"Dòng 3 bật đèn cảnh báo (P1 = FEH, LED P1.0 sáng). Thủ tục quét phím ghi P1 = FDH để kéo hàng 2 xuống 0: đèn cảnh báo tắt, LED P1.1 sáng thay. Hai thiết bị cùng cổng thì mỗi lần ghi cổng của thiết bị này phá trạng thái của thiết bị kia; I/O map phải tách chúng (đèn sang P2.7).","dev":{"led":true,"key":true},"fosc":12000000}];
const sim57=makeSim51(document.getElementById("m51-l57"),{id:"s57",presets:P57,ram:256});
makeEx51(document.getElementById("ex-l57"),"l57",[{"t":"Tìm chân xung đột","d":"<p>Bốn thiết bị muốn dùng cùng một cổng. Ô <code>30H<\/code>–<code>33H<\/code> chứa mặt nạ chân của từng thiết bị: bit <i>k<\/i> = 1 nghĩa là thiết bị dùng chân P<i>x<\/i>.<i>k<\/i>. Ghi vào <code>34H<\/code> mặt nạ các chân đã có thiết bị dùng, và vào <code>35H<\/code> mặt nạ các chân bị <b>từ hai thiết bị trở lên<\/b> cùng dùng (xung đột). Giữ nguyên 30H–33H. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>0FH, 80H, FFH, 00H<\/code> → <code>34H = FFH<\/code>, <code>35H = 8FH<\/code>.<\/p>","start":"        ORG     0000H\n; 30H..33H: mặt nạ chân của 4 thiết bị, cùng một cổng\n; Ghi 34H = chân đã dùng, 35H = chân bị dùng từ 2 lần\n; Viết code ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":15,"0x31":128,"0x32":255,"0x33":0,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":15,"0x31":128,"0x32":255,"0x33":0,"0x34":255,"0x35":143}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":4,"0x33":8,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":1,"0x31":2,"0x32":4,"0x33":8,"0x34":15,"0x35":0}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255}}},{"setup":{"iram":{"0x30":3,"0x31":6,"0x32":12,"0x33":0,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":3,"0x31":6,"0x32":12,"0x33":0,"0x34":15,"0x35":6}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":16,"0x33":16,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":16,"0x33":16,"0x34":16,"0x35":16}}}]},"hints":["Duyệt 4 mặt nạ bằng @R0 từ 30H; giữ hai biến trong R2 (đã dùng) và R3 (xung đột), cả hai bắt đầu bằng 0.","Với mỗi mặt nạ m: chân xung đột mới là những chân có trong m VÀ đã có trong R2. Tính cái đó trước khi thêm m vào R2.","Thứ tự trong mỗi vòng quan trọng: tìm chân xung đột với các mặt nạ trước, rồi mới thêm m vào tập đã dùng."],"why":"Một chân xung đột khi ít nhất hai thiết bị dùng nó, không cần cả bốn. Tích lũy “đã dùng” và kiểm mỗi mặt nạ mới với phần đã dùng cho đúng định nghĩa đó; bộ thử 5 (03H, 06H, 0CH) bắt cách AND cả bốn mặt nạ."},{"t":"Kiểm ngân sách thời gian","d":"<p>Ô <code>30H<\/code>–<code>33H<\/code> chứa số chu kỳ máy đo được của 4 tác vụ chạy trong cùng một tick (mỗi ô 8 bit, 0–255). Ô <code>38H<\/code> (byte cao) và <code>39H<\/code> (byte thấp) chứa ngân sách chu kỳ của tick. Ghi tổng 16 bit vào <code>34H<\/code> (byte cao) và <code>35H<\/code> (byte thấp); ghi <code>36H = 01H<\/code> nếu tổng ≤ ngân sách, ngược lại <code>36H = 00H<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: 120, 95, 180, 210 và ngân sách 700 (02BCH) → <code>34H:35H = 025DH<\/code>, <code>36H = 01H<\/code>.<\/p>","start":"        ORG     0000H\n; 30H..33H: chi phí 4 tác vụ (chu kỳ máy, mỗi ô 8 bit)\n; 38H:39H: ngân sách (byte cao : byte thấp)\n; Ghi 34H:35H = tổng, 36H = 01H nếu tổng ≤ ngân sách\n; Viết code ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":120,"0x31":95,"0x32":180,"0x33":210,"0x38":2,"0x39":188,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":2,"0x35":93,"0x36":1}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x38":0,"0x39":0,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":0,"0x35":0,"0x36":1}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x38":3,"0x39":232,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":3,"0x35":252,"0x36":0}}},{"setup":{"iram":{"0x30":100,"0x31":100,"0x32":100,"0x33":100,"0x38":1,"0x39":144,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":1,"0x35":144,"0x36":1}}},{"setup":{"iram":{"0x30":100,"0x31":100,"0x32":100,"0x33":101,"0x38":1,"0x39":144,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":1,"0x35":145,"0x36":0}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":1,"0x33":0,"0x38":2,"0x39":0,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":1,"0x35":255,"0x36":1}}},{"setup":{"iram":{"0x30":128,"0x31":128,"0x32":0,"0x33":0,"0x38":0,"0x39":255,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":1,"0x35":0,"0x36":0}}}]},"hints":["Cộng từng byte vào byte thấp của tổng bằng ADD, rồi cộng số nhớ vào byte cao bằng ADDC A,… với A = 0.","So sánh 16 bit bằng phép trừ: ngân sách − tổng. Trừ byte thấp trước (CLR C rồi SUBB), byte cao sau (SUBB tiếp nhận cờ mượn).","CY sau phép trừ 16 bit là kết quả (đảo lại): đổi thành 00H/01H không cần nhánh."],"why":"Tổng 4 byte có thể vượt 255 nên phải cộng 16 bit; so sánh cũng phải 16 bit, xét cờ mượn sau byte cao. Bộ thử 6 (01FFH ≤ 0200H) bắt lỗi chỉ so byte thấp; bộ thử 7 (0100H &gt; 00FFH) bắt lỗi quên số nhớ; bộ thử 4 kiểm “bằng nhau vẫn đạt”."},{"t":"Chạy máy trạng thái ≤ 150 chu kỳ","d":"<p>Máy trạng thái của bộ đếm có 3 trạng thái CHỜ (0), ĐẾM (1), BÁO (2) và 3 sự kiện: 0 = có sản phẩm, 1 = đủ hạn mức, 2 = nút xóa. Bảng chuyển trạng thái giống ví dụ 3. Danh sách sự kiện nằm từ ô <code>40H<\/code>, kết thúc bằng <code>FFH<\/code> (tối đa 8 sự kiện). Bắt đầu ở CHỜ, ghi trạng thái cuối vào <code>30H<\/code> và <b>số lần chuyển vào BÁO<\/b> (từ trạng thái khác sang BÁO) vào <code>31H<\/code>.<\/p><p>Code mẫu tính đúng trạng thái nhưng chưa đếm và chậm. Yêu cầu: toàn chương trình chạy không quá <b>150 chu kỳ máy<\/b> với mọi bộ thử (tính cả một lần <code>SJMP $<\/code>) và mã (kể cả bảng) không quá <b>50 byte<\/b>.<\/p>","start":"        ORG     0000H\n        MOV     R5,#0                   ; trạng thái CHỜ\n        MOV     R0,#40H                 ; con trỏ sự kiện\nVONG:   MOV     A,@R0\n        CJNE    A,#0FFH,BUOC            ; FFH = hết danh sách\n        SJMP    XONG\nBUOC:   MOV     R6,A\n        MOV     A,R5\n        MOV     B,#4\n        MUL     AB                      ; A = 4 × trạng thái\n        ADD     A,R6\n        MOV     DPTR,#NEXT\n        MOVC    A,@A+DPTR               ; trạng thái mới\n        MOV     R5,A\n; Viết thêm: đếm số lần vào BÁO, ghi vào 31H\n        INC     R0\n        SJMP    VONG\nXONG:   MOV     30H,R5\n        SJMP    $\nNEXT:   DB      1,0,0,0                 ; từ CHỜ\n        DB      1,2,0,1                 ; từ ĐẾM\n        DB      2,2,0,2                 ; từ BÁO\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":0,"0x41":0,"0x42":1,"0x43":0,"0x44":2,"0x45":0,"0x46":255,"0x30":238,"0x31":238}},"expect":{"iram":{"0x30":1,"0x31":1}}},{"setup":{"iram":{"0x40":255,"0x30":238,"0x31":238}},"expect":{"iram":{"0x30":0,"0x31":0}}},{"setup":{"iram":{"0x40":0,"0x41":1,"0x42":0,"0x43":0,"0x44":0,"0x45":0,"0x46":0,"0x47":0,"0x48":255,"0x30":238,"0x31":238}},"expect":{"iram":{"0x30":2,"0x31":1}}},{"setup":{"iram":{"0x40":0,"0x41":1,"0x42":2,"0x43":0,"0x44":1,"0x45":2,"0x46":0,"0x47":1,"0x48":255,"0x30":238,"0x31":238}},"expect":{"iram":{"0x30":2,"0x31":3}}},{"setup":{"iram":{"0x40":1,"0x41":1,"0x42":2,"0x43":2,"0x44":255,"0x30":238,"0x31":238}},"expect":{"iram":{"0x30":0,"0x31":0}}},{"setup":{"iram":{"0x40":0,"0x41":1,"0x42":1,"0x43":2,"0x44":1,"0x45":0,"0x46":1,"0x47":2,"0x48":255,"0x30":238,"0x31":238}},"expect":{"iram":{"0x30":0,"0x31":2}}}],"maxCyc":150,"maxBytes":50},"hints":["Chạy code mẫu với 8 sự kiện: mỗi vòng tốn bao nhiêu chu kỳ? MOV B,#4 + MUL AB (6 chu kỳ) và MOV DPTR trong vòng lặp là phần đắt nhất.","4 × trạng thái chỉ cần hai lệnh RL A (trạng thái &lt; 64); DPTR chỉ cần nạp một lần trước vòng lặp; ADD A,@R0 cộng thẳng sự kiện mà không cần R6. Kiểm FFH bằng JB ACC.7 thay CJNE + SJMP.","Đánh dấu ô bảng ứng với lần vào BÁO bằng một bit thừa; sau khi tra, kiểm bit đó rồi xóa."],"why":"Bảng chuyển trạng thái có thể mang cả “hành động” (ở đây là cờ vừa vào BÁO), nên vòng lặp không cần so sánh trạng thái cũ và mới. Bỏ MUL AB, nạp DPTR một lần và đổi CJNE + SJMP thành JB đưa mỗi sự kiện xuống 15 chu kỳ; 8 sự kiện có 3 lần vào BÁO tốn 141 chu kỳ, mã 45 byte."}]);

makeQuiz("quiz57","score57",[{"q": "Yêu cầu nào dưới đây viết đúng kiểu đặc tả đo được?", "o": ["Cảnh báo nhanh khi đủ hàng", "Đèn cảnh báo phải hoạt động tốt", "Bật đèn cảnh báo trong ≤ 10 ms sau sản phẩm thứ N (N nhập từ bàn phím)", "Dùng ngắt để cảnh báo cho nhanh"], "a": 2, "e": "Yêu cầu đo được nói rõ đại lượng (thời gian từ sản phẩm cuối tới khi đèn bật), ngưỡng (10 ms) và điều kiện (N). “Dùng ngắt” là cách làm, không phải yêu cầu."}, {"q": "Mặt nạ chân đã cấp trên P2 là 8FH. Thiết bị nào thêm vào P2 mà KHÔNG xung đột?", "o": ["LCD 8 bit (mặt nạ FFH)", "LCD 4 bit ở P2.4–P2.7 (mặt nạ F0H)", "Động cơ bước ở P2.0–P2.3 (mặt nạ 0FH)", "Thiết bị dùng P2.4–P2.6 (mặt nạ 70H)"], "a": 3, "e": "70H AND 8FH = 00H nên không có chân chung. F0H AND 8FH = 80H (đụng chân cảnh báo P2.7), 0FH AND 8FH = 0FH (đụng chân chọn chữ số)."}, {"q": "Tick 1 ms ở 12 MHz, ngân sách cấp 70 %. Bốn tác vụ đo được 150, 200, 180, 190 chu kỳ. Kết luận nào đúng?", "o": ["Đạt vì 720 < 1 000", "Vượt ngân sách 20 chu kỳ (720 > 700), phải tối ưu hoặc chia tác vụ sang tick khác", "Đạt vì mỗi tác vụ đều dưới 255 chu kỳ", "Không kết luận được vì tổng vượt 8 bit"], "a": 1, "e": "Tổng 150 + 200 + 180 + 190 = 720 chu kỳ, lớn hơn ngân sách 700 (70 % của 1 000). Dưới 1 000 chưa đủ vì biên 30 % dành cho ngắt và yêu cầu mới; tổng vượt 255 thì cộng 16 bit."}, {"q": "Chương trình đặt biến ở 08H và không có lệnh MOV SP,… Lệnh ACALL đầu tiên làm gì với biến đó?", "o": ["Ghi đè byte thấp của địa chỉ trở về lên 08H", "Không ảnh hưởng vì ngăn xếp nằm ở RAM cao", "Trình dịch báo lỗi trùng địa chỉ", "Ghi địa chỉ trở về vào 06H, 07H"], "a": 0, "e": "Sau reset SP = 07H; ACALL tăng SP trước khi ghi, nên byte thấp địa chỉ trở về vào 08H, byte cao vào 09H. Không có lỗi hay cảnh báo nào (ví dụ 4)."}, {"q": "Bộ chạy bảng chuyển trạng thái tính chỉ số = 4 × trạng thái + sự kiện rồi MOVC. Trạng thái bị hỏng thành 5. Điều gì xảy ra nếu không kiểm phạm vi?", "o": ["MOVC đọc một byte ngoài bảng (byte của bảng khác hoặc của lệnh), máy chạy tiếp với trạng thái sai mà không báo lỗi", "CPU tự reset", "MOVC trả về 00H nên máy về CHỜ", "Trình mô phỏng và chip thật đều báo lỗi truy cập bảng"], "a": 0, "e": "MOVC chỉ cộng A với DPTR và đọc bộ nhớ chương trình; không có kiểm biên nào. Đặc tả phải quy định trạng thái an toàn và code phải kiểm phạm vi trước khi tra bảng."}]);

